INSERT INTO feature VALUES('signature-help','editor','Signature help','language-server','implemented','ordinary',NULL,'Inside a call''s arguments, one signature per spine of the context stack, the innermost first and active: the head the called name was written with — a declaration''s, a constructor''s or a binder''s function type — on one line, else the head and its type, with its documentation, each parameter with the `///` run written before it (also its hover), and the argument the position writes. A space after a head that still takes an argument opens its next slot, and a space after a saturated call opens none. Read from the context stack and a signature index per closure read off parses already made, the callee from the referent index; a refused declaration keeps its uses.','surface-lsp surface-lsp-core surface-dispatcher surface-lowering','crates/surface-lsp-core/src/signature.rs crates/surface-lsp/tests/session.rs crates/surface-lowering/tests/scopes.rs',NULL,'#764');
